function s(e){let n=e;const a=new Set;return{get:()=>n,set:t=>{n=t,a.forEach(l=>l(n))},subscribe:t=>(a.add(t),t(n),()=>a.delete(t))}}const i=s(null),f=s(null),u=s(""),d=s(0);function g(e){f.set(e),i.set("article")}function m(){i.set(null),f.set(null)}function M(e){if(!e)return"-";const n=new Date(e),t=new Date().getTime()-n.getTime(),l=Math.floor(t/1e3),r=Math.floor(l/60),o=Math.floor(r/60),c=Math.floor(o/24);return r<1?"Şimdi":r<60?`${r} dk önce`:o<24?`${o} saat önce`:c===1?"Dün":`${c} gün önce`}function h(e){return e>=80?{label:`${e} KRİTİK`,className:"score-critical"}:e>=50?{label:`${e} YÜKSEK`,className:"score-high"}:e>=30?{label:`${e} ORTA`,className:"score-medium"}:{label:`${e} DÜŞÜK`,className:"score-low"}}export{i as a,u as b,m as c,M as f,h as g,g as o,d as r,f as s};
